from pathlib import Path
import shutil
root=Path('client-testimonials')
projects=[('limitlessbrainlab','Limitless Brain Lab','health programme lead','operations/QA manager','clinic-adjacent consultation room','bright home office'),('enerex','Enerex','B2B product marketer','technical implementation lead','modern office meeting room','home office with screen'),('balletpro','BalletPro','e-commerce manager','customer experience lead','retail stockroom','dance studio office'),('cuddlespetbrand','Cuddles Dog Bakery','founder','orders/community coordinator','small bakery workspace','home packing desk'),('myzochocolate','MYZO Chocolate','brand manager','e-commerce operations lead','bright tasting room','home office / packing area'),('bidet-toilets','Bidet Toilets Store','product marketing manager','technical sales coordinator','bathroom showroom office','home office with product catalogue'),('farawayfinds','Faraway Finds','e-commerce manager','QA coordinator','small retail office','home workspace'),('mrca','MRCA','corporate communications manager','portfolio operations lead','industrial office','quiet home office'),('wellsind','Wells Industries','marketing manager','sales operations lead','design studio','factory-adjacent office'),('wisconic','Wisconic','technical marketing manager','operations coordinator','engineering office','home office with product samples')]
angles=[('Personal project experience','Situation → problem → discovery → action → reaction','medium close-up, daylight, restrained gestures','laptop showing permitted public site pages; annotated QA notes; mobile layout review'),('Business / team experience','Unexpected discovery → why it mattered → Abdul\'s handling → what changed → recommendation','wider framing, warmer practical light, conversational posture','team checklist; developer handoff; responsive retest; screen recording without metrics')]
for slug,name,sp1,sp2,env1,env2 in projects:
 d=root/slug; vd=d/'videos'; vd.mkdir(exist_ok=True)
 source1=d/'testimonial-01.md'; source2=d/'testimonial-02.md'
 for i,(profile,arc,env,broll) in enumerate([(sp1,angles[0][1],env1,angles[0][3]),(sp2,angles[1][1],env2,angles[1][3])],1):
  script=d/f'testimonial-0{i}-script.md'
  if not script.exists(): shutil.copy(d/f'testimonial-0{i}.md',script)
  prompt=f'''# Video {i:02d} generation prompt — {name}\n\nCreate a fictional presenter / demo speaker testimonial. Do not imply this person is a real client. The client must approve the script, identity treatment and project claims before publication. Do not imitate a real person or use a real client's likeness or voice.\n\n**Presenter:** {profile}, clearly labelled “Fictional presenter — demo only”. Use a unique synthetic voice, distinct from every other project and from Video {3-i:02d}; natural accent, breathing, blinking, subtle head movement, small posture shifts and restrained hand gestures. Conversational, not an advert.\n**Story arc:** {arc}.\n**Environment:** {env}. Do not reuse the other video's set, clothing, framing or lighting.\n**Camera:** {'4K-style' if i==1 else '1080p or higher'} natural skin texture, shallow but believable depth of field, no glossy commercial look. {'Medium close-up, 16:9, daylight.' if i==1 else 'Wider 16:9 frame, warmer practical light, slight off-camera interviewer feel.'}\n**B-roll:** {broll}. Use only actual public website screens or client-supplied material. No invented analytics, dashboards, outcomes or numbers.\n**Audio:** clean dialogue, subtle room tone, no overpowering music, accurate lip sync.\n**Subtitles:** accurate verbatim captions, high contrast, bottom safe area, no kinetic typography.\n**Truth constraint:** only use the attached finalized script. Retain language that says claims require confirmation. Never state that Abdul increased revenue, sales, traffic, conversion, speed or rankings unless the client adds dated evidence.\n**Deliverable:** H.264 MP4, 1920x1080, 24/25/30 fps, AAC audio, 45–90 seconds.\n**Vertical variant:** reframe the subject intelligently for 1080x1920, 9:16; preserve hands and relevant B-roll where possible.\n'''
  (vd/f'testimonial-0{i}-generation-prompt.md').write_text(prompt)
 (d/'video-production-notes.md').write_text(f'''# Video production notes — {name}\n\nTwo independent demo-video concepts are prepared. Both presenters are fictional until a real client supplies identity, approval and release.\n\n| Video | Presenter | Setting | Story | Status |\n|---|---|---|---|---|\n| 01 | {sp1} | {env1} | Personal project experience | Prompt and script ready; render pending |\n| 02 | {sp2} | {env2} | Business / team experience | Prompt and script ready; render pending |\n\n## Render files\n\nThe environment has no connected video-generation or MP4 rendering tool. Therefore no MP4 or vertical MP4 is claimed as generated. The following files remain to be rendered by a connected system:\n\n- `videos/testimonial-01.mp4`\n- `videos/testimonial-02.mp4`\n- `videos/testimonial-01-vertical.mp4`\n- `videos/testimonial-02-vertical.mp4`\n\n## Required output\n\nH.264, 1080p minimum, 16:9, 24/25/30 fps, clean AAC dialogue, synchronized subtitles, plus intelligently reframed 1080x1920 versions.\n''')
(root/'VIDEO-RENDER-STATUS.md').write_text('''# Video render status\n\nPrepared 20 unique generation prompts and 20 finalized script references across 10 projects. No MP4 files have been generated because this coding environment does not provide a connected avatar/video rendering tool.\n\nAll presenters are explicitly fictional demo speakers. Before rendering, attach each project\'s client-approved statement and replace or revise any unsupported wording.\n''')
print('prepared prompts for',len(projects)*2,'videos')
